from itertools import combinations

def find_golomb_ruler(marks):
    for attempt in range(1, 10000):
        ruler = [0, attempt]
        for i in range(2, marks):
            for j in range(ruler[-1] + 1, 10000):
                distances = set()
                for pair in combinations(ruler + [j], 2):
                    distances.add(abs(pair[0] - pair[1]))
                if len(distances) == len(ruler) + 1:
                    ruler.append(j)
                    break
            else:
                break
        else:
            return ruler
    return None

print(find_golomb_ruler(6))
